// 按原题假定乘积在 int 可表示范围内；结果数组不计额外空间。
void calMulMax(int A[], int res[], int n) {
    if (n <= 0) return;
    int lo = A[n-1], hi = A[n-1];
    for (int i = n-1; i >= 0; --i) {
        if (A[i] < lo) lo = A[i];
        if (A[i] > hi) hi = A[i];
        int p = A[i] * lo, q = A[i] * hi;
        res[i] = p > q ? p : q;
    }
}

